"""Preserve already personally read complete literals; projections are conditional static facts."""
from pathlib import Path
import json,re
B=Path(__file__).resolve().parent
R=Path('/workspace/pokemon-essentials')
def sections(path):
    lines=(R/path).read_text(encoding='utf-8-sig').splitlines();records=[];cur=None
    for number,line in enumerate(lines,1):
        if not line.strip() or line.lstrip().startswith('#'):continue
        if line.startswith('['):
            if cur:cur['source_range'][1]=number-1
            cur={'ordinal':len(records)+1,'id_symbol_text':line[1:-1],'source_range':[number,len(lines)],'fields':[]};records.append(cur)
        else:
            m=re.fullmatch(r'(\w+)\s*=\s*(.*)',line);assert m and cur
            cur['fields'].append({'line':number,'key':m[1],'original_value':m[2],'original_line':line})
    return records
paths=['PBS/Shadow Pokémon backup/items_shadow_pkmn.txt','PBS/Shadow Pokémon backup/moves_shadow_pkmn.txt','PBS/Shadow Pokémon backup/shadow_pokemon.txt']
files=[]
for path,expected in zip(paths,[4,18,131]):
    records=sections(path);assert len(records)==expected
    for record in records:
        p={x['key']:x['original_value'] for x in record['fields']}
        if 'items_' in path:
            assert set(p)<=set('Name NamePlural PortionName PortionNamePlural Pocket Price FieldUse BattleUse Description'.split())
            assert p['FieldUse']=='OnPokemon' and p.get('BattleUse','OnPokemon')=='OnPokemon'
            value={'id_symbol_text':record['id_symbol_text'],'real_name':p['Name'],'real_name_plural':p['NamePlural'],'real_portion_name':p.get('PortionName'),'real_portion_name_plural':p.get('PortionNamePlural'),'pocket':int(p['Pocket']),'price':int(p['Price']),'sell_price':int(p['Price'])//2,'bp_price':1,'field_use':1,'battle_use':1 if 'BattleUse'in p else 0,'flags':[],'consumable':True,'show_quantity':None,'move':None,'real_description':p['Description'],'pbs_file_suffix':'shadow_pkmn'}
        elif 'moves_' in path:
            assert set(p)<=set('Name Type Category Power Accuracy TotalPP Target FunctionCode Flags EffectChance Description'.split())
            value={'id_symbol_text':record['id_symbol_text'],'real_name':p['Name'],'type_symbol_text':p['Type'],'category':['Physical','Special','Status'].index(p['Category']),'power':int(p.get('Power','0')),'accuracy':int(p['Accuracy']),'total_pp':int(p['TotalPP']),'target_symbol_text':p['Target'],'priority':0,'function_code':p['FunctionCode'],'flags':p['Flags'].split(','),'effect_chance':int(p.get('EffectChance','0')),'real_description':p['Description'],'pbs_file_suffix':'shadow_pkmn'}
        else:
            assert set(p)=={'GaugeSize','Moves'}
            value={'id_symbol_text':record['id_symbol_text'],'species_symbol_text':record['id_symbol_text'],'form':0,'gauge_size':int(p['GaugeSize']),'moves_symbol_text':p['Moves'].split(','),'flags':[],'pbs_file_suffix':''}
        record['conditional_schema_constructor_values']=value
        record['qualification']='Every original field/value personally read. Types/defaults interpreted from complete fixed schema/constructor; Symbol values explicitly represented as text. Actual registry loading, reference existence and target execution not inferred.'
    files.append({'path':path,'records':records,'record_count':len(records),'explicit_field_count':sum(len(x['fields']) for x in records)})
dex=[];current=None
for number,line in enumerate((R/'PBS/regional_dexes.txt').read_text(encoding='utf-8-sig').splitlines(),1):
    if not line.strip() or line.startswith('#'):continue
    if line.startswith('['):
        current={'section_index':int(line[1:-1]),'source_header_line':number,'ordered_species_tokens':[]};dex.append(current)
    else:
        for token in line.split(','):
            canonical=token.upper().strip();canonical={'NIDORANFE':'NIDORANfE','NIDORANMA':'NIDORANmA'}.get(canonical,canonical)
            current['ordered_species_tokens'].append({'ordinal_1based':len(current['ordered_species_tokens'])+1,'source_line':number,'original_token':token,'conditional_parseSpecies_lookup_string':canonical})
assert [len(x['ordered_species_tokens']) for x in dex]==[151,256]
assert all(len({x['original_token'] for x in a['ordered_species_tokens']})==len(a['ordered_species_tokens']) for a in dex)
